# plot_results.py
#
# Usage:
#   python plot_results.py experiment_results.csv
#
# This script reads the CSV generated by Main.py and creates several PNG plots:
#   - avg_read_latency.png
#   - avg_path_distance.png
#   - speculation_success_rate.png
#   - max_queue_depth.png
#   - messages_created.png

import csv
import sys
from pathlib import Path

import matplotlib.pyplot as plt


def read_results(csv_path):
    rows = []

    with open(csv_path, "r", newline="") as f:
        reader = csv.DictReader(f)

        for row in reader:
            parsed = {}
            for key, value in row.items():
                if key == "experiment":
                    parsed[key] = value
                else:
                    try:
                        parsed[key] = float(value)
                    except ValueError:
                        parsed[key] = value

            rows.append(parsed)

    return rows


def bar_chart(rows, metric, ylabel, title, output_path):
    experiment_names = [row["experiment"] for row in rows]
    values = [row.get(metric, 0.0) for row in rows]

    plt.figure(figsize=(11, 6))
    plt.bar(experiment_names, values)
    plt.ylabel(ylabel)
    plt.title(title)
    plt.xticks(rotation=20, ha="right")
    plt.tight_layout()
    plt.savefig(output_path, dpi=200)
    plt.close()


def main():
    if len(sys.argv) != 2:
        print("Usage: python plot_results.py experiment_results.csv")
        sys.exit(1)

    csv_path = Path(sys.argv[1])

    if not csv_path.exists():
        print(f"Could not find CSV file: {csv_path}")
        sys.exit(1)

    rows = read_results(csv_path)

    if not rows:
        print("CSV file contained no rows.")
        sys.exit(1)

    output_dir = csv_path.parent / "plots"
    output_dir.mkdir(exist_ok=True)

    bar_chart(
        rows,
        metric="average_read_latency",
        ylabel="Average Read Latency (cycles)",
        title="Average Read Latency by Configuration",
        output_path=output_dir / "avg_read_latency.png",
    )

    bar_chart(
        rows,
        metric="average_authoritative_read_latency",
        ylabel="Average Authoritative Read Latency (cycles)",
        title="Average Authoritative Read Latency by Configuration",
        output_path=output_dir / "avg_authoritative_read_latency.png",
    )

    bar_chart(
        rows,
        metric="average_speculative_read_latency",
        ylabel="Average Speculative Read Latency (cycles)",
        title="Average Speculative Read Latency by Configuration",
        output_path=output_dir / "avg_speculative_read_latency.png",
    )

    bar_chart(
        rows,
        metric="average_path_distance",
        ylabel="Average Path Distance (hops)",
        title="Average Message Path Distance by Configuration",
        output_path=output_dir / "avg_path_distance.png",
    )

    bar_chart(
        rows,
        metric="speculative_success_rate_percent",
        ylabel="Speculative Success Rate (%)",
        title="Speculative Success Rate by Configuration",
        output_path=output_dir / "speculation_success_rate.png",
    )

    bar_chart(
        rows,
        metric="max_queue_depth",
        ylabel="Maximum Switch Queue Depth",
        title="Maximum Queue Depth by Configuration",
        output_path=output_dir / "max_queue_depth.png",
    )

    bar_chart(
        rows,
        metric="messages_created",
        ylabel="Messages Created",
        title="Messages Created by Configuration",
        output_path=output_dir / "messages_created.png",
    )

    print(f"Saved plots to: {output_dir}")


if __name__ == "__main__":
    main()
